# Bank zadań autorskich — etap 2: wypracowania (partia 5: zamknięcie etapu — 8 tematów).
BANK = {}

M = 'Wypracowanie (wypowiedź argumentacyjna). Zadanie autorskie IndexLab w formacie egzaminu maturalnego od 2023 r. Twoja wypowiedź powinna liczyć minimum 300 wyrazów.'

BANK['umiejetnosci'] = [
 B('Wypracowanie — starożytność: dziedzictwo Greków', M,
   T('wypracowanie', 15, 'Starożytni Grecy stworzyli fundamenty kultury europejskiej. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, naukowo-filozoficzny i artystyczny.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, choć kultura europejska ma także korzenie rzymskie i chrześcijańskie).\n\n'
     'Mówi się, że Europa stoi na trzech filarach: greckiej filozofii, rzymskim prawie i chrześcijańskiej religii. Uważam, że to właśnie Grecy położyli fundament pod pierwszy, a w dużej mierze także pod pozostałe dwa, bo ich myśl przejęli i rozwinęli zarówno Rzymianie, jak i chrześcijanie. Dlatego teza jest w moim przekonaniu prawdziwa.\n\n'
     'W aspekcie politycznym Grecy stworzyli pojęcia, którymi posługujemy się do dziś. Słowa „demokracja”, „polityka”, „tyrania”, „oligarchia” pochodzą z greki. Ateńska demokracja, ukształtowana po reformach Klejstenesa, wprowadziła zgromadzenie obywateli, losowanie urzędników i odpowiedzialność polityków przed ludem. Arystoteles w „Polityce” opisał i porównał ustroje, a jego podział na monarchię, arystokrację i politeję oraz ich wypaczenia był podstawą europejskiej myśli politycznej aż do czasów nowożytnych.\n\n'
     'W aspekcie naukowo-filozoficznym Grecy jako pierwsi szukali wyjaśnień świata w rozumie, a nie w mitach. Filozofowie z Jonii, jak Tales z Miletu, pytali o praprzyczynę wszechrzeczy. Sokrates, Platon i Arystoteles stworzyli podstawy etyki, logiki i teorii poznania, a Arystoteles przez całe średniowiecze był „Filozofem” — punktem odniesienia dla Tomasza z Akwinu. Euklides uporządkował geometrię, Archimedes rozwinął fizykę, a Hipokrates uczynił z medycyny dziedzinę opartą na obserwacji. Przysięgę Hipokratesa w zmienionej formie składają lekarze do dziś.\n\n'
     'W aspekcie artystycznym Grecy stworzyli kanony piękna, do których Europa wracała wielokrotnie. Porządki architektoniczne — dorycki, joński i koryncki — oraz świątynie, jak Partenon, były wzorem dla Rzymian, renesansu i klasycyzmu, czego przykładem jest warszawski Teatr Wielki czy kościół św. Aleksandra. Rzeźba grecka wyznaczyła ideał proporcji ludzkiego ciała. Tragedia i komedia, z Ajschylosem, Sofoklesem i Arystofanesem, zapoczątkowały europejski teatr, a „Iliada” i „Odyseja” — literaturę.\n\n'
     'Można argumentować, że kultura europejska jest w równym stopniu dziedzictwem Rzymu i chrześcijaństwa: to Rzym dał prawo, łacinę i organizację państwa, a chrześcijaństwo — system wartości i Kościół. To prawda, ale Rzymianie sami uczyli się od Greków, a teologia chrześcijańska korzystała z filozofii Platona i Arystotelesa.\n\n'
     'Podsumowując, Grecy dali Europie język polityki, metody myślenia naukowego i kanony sztuki. Choć kultura europejska ma więcej korzeni, to grecki jest najstarszy i najgłębszy. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → polityczny (słownictwo, demokracja ateńska, Arystoteles o ustrojach) → naukowo-filozoficzny (filozofowie jońscy, Sokrates–Platon–Arystoteles, Euklides, Archimedes, Hipokrates) → artystyczny (porządki, Partenon, klasycyzm, rzeźba, teatr, Homer) → kontrargument (Rzym, chrześcijaństwo) → wniosek.\n\nTypowe błędy: wymienianie nazwisk bez wskazania, co z ich dorobku przetrwało; brak przykładów późniejszych nawiązań.')),

 B('Wypracowanie — średniowiecze: Bolesław Chrobry', M,
   T('wypracowanie', 15, 'Panowanie Bolesława Chrobrego było okresem największej potęgi państwa pierwszych Piastów. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji politykę zagraniczną, politykę wewnętrzną i sprawy kościelne.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, choć potęga ta była krucha i szybko się załamała).\n\n'
     'Bolesław Chrobry panował w latach 992–1025, przejmując państwo zbudowane przez ojca, Mieszka I. Gdy umierał, był pierwszym koronowanym królem Polski, a jego państwo należało do najważniejszych w Europie Środkowej. Uważam, że był to okres największej potęgi państwa pierwszych Piastów, choć opierała się ona na osobie władcy i rozpadła się w kryzysie lat 30. XI w.\n\n'
     'W polityce zagranicznej Bolesław prowadził śmiałą ekspansję. Początkowo współpracował z cesarzem Ottonem III, który marzył o odnowieniu cesarstwa jako wspólnoty chrześcijańskich państw. Po śmierci Ottona Bolesław przez kilkanaście lat walczył z cesarzem Henrykiem II. Pokój w Budziszynie (1018) pozostawił mu Łużyce i Milsko. W tym samym roku Bolesław wyprawił się na Kijów, osadził na tronie swojego zięcia Świętopełka i przyłączył Grody Czerwieńskie. Przez pewien czas panował też w Czechach.\n\n'
     'W polityce wewnętrznej Bolesław rozbudował drużynę książęcą, która według kronikarzy liczyła kilka tysięcy zbrojnych, i sieć grodów zarządzanych przez jego urzędników. Utrzymywał jedność państwa i dbał o jego prestiż — kroniki opisują przepych jego dworu. W 1025 r. koronował się na króla, co podniosło rangę Polski do poziomu Czech czy Węgier i oznaczało pełną niezależność od cesarstwa.\n\n'
     'W sprawach kościelnych największym sukcesem był zjazd gnieźnieński (1000). Wykorzystując męczeńską śmierć biskupa Wojciecha, którego ciało wykupił od Prusów, Bolesław doprowadził do jego kanonizacji. Otton III przybył do Gniezna jako pielgrzym, a utworzenie arcybiskupstwa gnieźnieńskiego z biskupstwami w Krakowie, Wrocławiu i Kołobrzegu uniezależniło polski Kościół od niemieckiego Magdeburga. Kult św. Wojciecha stał się ważnym elementem tożsamości państwa.\n\n'
     'Można argumentować, że potęga Chrobrego była pozorna, bo opierała się na łupach i wysiłku wojennym ponad siły kraju, a już za jego syna Mieszka II państwo przeżyło kryzys, utraciło zdobycze i koronę. To ważny argument — ale świadczy o słabości następców i trudnych warunkach, a nie o tym, że za Chrobrego państwo nie było potężne.\n\n'
     'Podsumowując, za Bolesława Chrobrego państwo Piastów osiągnęło największy zasięg terytorialny, rangę królestwa i niezależną organizację kościelną. Dlatego uważam tezę za prawdziwą, pamiętając, że była to potęga krótkotrwała.',
     'Plan: stanowisko „tak, ale krucha potęga” → zagraniczna (Otton III, wojny z Henrykiem II, Budziszyn 1018, Kijów i Grody Czerwieńskie, Czechy) → wewnętrzna (drużyna, grody, prestiż, koronacja 1025) → kościelna (św. Wojciech, zjazd 1000, arcybiskupstwo i biskupstwa) → kontrargument (kryzys za Mieszka II) → wniosek.\n\nTypowe błędy: przypisywanie Chrobremu chrztu Polski (to Mieszko I, 966); pomijanie znaczenia arcybiskupstwa.')),

 B('Wypracowanie — nowożytność: absolutyzm a parlamentaryzm', M,
   T('wypracowanie', 15, 'W XVII w. monarchia absolutna okazała się ustrojem skuteczniejszym niż monarchia parlamentarna. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, odwołując się do przykładów trzech państw europejskich.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa tylko częściowo — zależało to od tego, czy parlamentaryzm opierał się na sprawnym państwie).\n\n'
     'W XVII w. w Europie rywalizowały dwa modele władzy: monarchia absolutna, w której król skupiał całą władzę, i ustrój, w którym ważną rolę odgrywał parlament. Uważam, że absolutyzm nie był z natury skuteczniejszy — o sukcesie decydowało to, czy państwo miało sprawny skarb, wojsko i administrację. Pokazują to trzy przykłady: Francja, Anglia i Rzeczpospolita.\n\n'
     'Francja Ludwika XIV jest klasycznym przykładem skutecznego absolutyzmu. Po okresie wojen religijnych i buntu Frondy król rządził samodzielnie od 1661 r. Minister finansów Jean-Baptiste Colbert prowadził politykę merkantylizmu, rozwijał manufaktury i flotę, a stała armia była największa w Europie. Wersal stał się wzorem dla władców całego kontynentu, a Francja — najpotężniejszym państwem. Jednak kosztowne wojny i odwołanie edyktu nantejskiego (1685) osłabiły kraj i zostawiły ogromne długi, co przyczyniło się do rewolucji w następnym stuleciu.\n\n'
     'Anglia pokazuje, że parlamentaryzm mógł być skuteczny. Po rewolucji, egzekucji Karola I (1649) i rządach Cromwella, a następnie po „chwalebnej rewolucji” (1688) i uchwaleniu Bill of Rights (1689) władza króla została ograniczona przez parlament. Parlament kontrolował podatki, ale właśnie dlatego społeczeństwo chętniej je płaciło. Anglia zbudowała najsilniejszą flotę świata, rozwijała handel i kolonie, a w XVIII w. stała się kolebką rewolucji przemysłowej.\n\n'
     'Rzeczpospolita jest przykładem parlamentaryzmu nieskutecznego. Demokracja szlachecka w XVII w. coraz gorzej działała: od 1652 r. zrywano sejmy na podstawie liberum veto, skarb był pusty, a armia zbyt mała. Kraj nie poradził sobie z powstaniem Chmielnickiego, potopem szwedzkim i wojnami z Moskwą i Turcją. Problemem nie był jednak sam udział szlachty we władzy, lecz brak sprawnych instytucji wykonawczych i rosnąca rola magnatów.\n\n'
     'Zwolennicy tezy podkreślają, że w XVII w. absolutyzm umacniał się w większości krajów: we Francji, Hiszpanii, Szwecji, Prusach i Rosji. To prawda, ale przykład Anglii pokazuje, że ustrój parlamentarny mógł być równie, a w dłuższej perspektywie nawet bardziej skuteczny.\n\n'
     'Podsumowując, absolutyzm był skuteczniejszy niż słaby parlamentaryzm Rzeczypospolitej, ale nie niż angielski ustrój parlamentarny. Dlatego teza jest prawdziwa tylko częściowo.',
     'Plan: stanowisko „częściowo” → Francja (Ludwik XIV, Colbert, armia, Wersal / koszty, 1685) → Anglia (rewolucja, 1688, Bill of Rights, flota i handel) → Rzeczpospolita (liberum veto 1652, pusty skarb, klęski) → kontrargument (absolutyzm w większości państw) → wniosek.\n\nTypowe błędy: utożsamianie Rzeczypospolitej z „parlamentaryzmem w ogóle”; brak dat kluczowych aktów (1661, 1689, 1652).')),

 B('Wypracowanie — XVIII w.: oświecenie i polityka', M,
   T('wypracowanie', 15, 'Idee oświecenia zmieniły sposób sprawowania władzy w państwach europejskich i amerykańskich. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt ustrojowy, społeczny i edukacyjny.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, choć zmiany nastąpiły w różnym tempie i często dopiero w wyniku rewolucji).\n\n'
     'Oświecenie było epoką wiary w rozum, naukę i postęp. Jego myśliciele — Locke, Monteskiusz, Wolter, Rousseau — pytali, skąd pochodzi władza i jakie są granice jej działania. Uważam, że ich idee rzeczywiście zmieniły sposób sprawowania władzy w Europie i Ameryce, choć często nie przez stopniowe reformy, lecz przez rewolucje.\n\n'
     'W aspekcie ustrojowym najważniejsze były koncepcje umowy społecznej, suwerenności ludu i trójpodziału władzy. John Locke uważał, że władza pochodzi od ludzi i ma chronić ich prawa naturalne: do życia, wolności i własności. Monteskiusz w „O duchu praw” (1748) opisał podział na władzę ustawodawczą, wykonawczą i sądowniczą. Idee te wcielono w życie w Deklaracji Niepodległości (1776) i konstytucji Stanów Zjednoczonych (1787), w Deklaracji praw człowieka i obywatela (1789) we Francji oraz w Konstytucji 3 maja (1791), która wprowadzała trójpodział władzy i zasadę zwierzchnictwa narodu.\n\n'
     'W aspekcie społecznym oświeceniowa krytyka przywilejów i nietolerancji podważała dawny porządek. Wolter walczył z fanatyzmem religijnym, a Rousseau pisał o równości ludzi. W monarchiach absolutyzmu oświeconego — Prusach Fryderyka II, Austrii Józefa II i Rosji Katarzyny II — władcy wprowadzali reformy: zniesienie tortur, tolerancję religijną (patent tolerancyjny Józefa II, 1781), ograniczanie pańszczyzny. Zarazem ci sami władcy dokonali rozbiorów Rzeczypospolitej, a reformy służyły przede wszystkim wzmocnieniu państwa.\n\n'
     'W aspekcie edukacyjnym oświecenie uznało, że państwo powinno kształcić obywateli. W Polsce Komisja Edukacji Narodowej (1773) stworzyła świecki system szkolny z nowymi podręcznikami i nauką przedmiotów przyrodniczych. W Prusach i Austrii wprowadzono obowiązek szkolny. Encyklopedia Diderota i d’Alemberta miała udostępnić wiedzę szerokim kręgom wykształconych ludzi.\n\n'
     'Zwolennicy przeciwnego poglądu przypominają, że w wielu państwach — w Rosji, Austrii czy Prusach — po oświeceniu nadal panował absolutyzm, a monarchowie przyjmowali idee wybiórczo. To prawda, ale nawet tam sposób rządzenia się zmienił: władca przedstawiał się jako „pierwszy sługa państwa”, a nie władca z woli Boga.\n\n'
     'Podsumowując, idee oświecenia stworzyły podstawy nowoczesnych konstytucji, praw człowieka i edukacji publicznej. Choć zmiany przebiegały różnie w różnych krajach, uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → ustrojowy (Locke, Monteskiusz, 1776, 1787, 1789, 1791) → społeczny (Wolter, Rousseau, absolutyzm oświecony, patent tolerancyjny / rozbiory) → edukacyjny (KEN 1773, obowiązek szkolny, Encyklopedia) → kontrargument (absolutyzm trwał) → wniosek.\n\nTypowe błędy: wyliczanie filozofów bez pokazania, gdzie ich idee wprowadzono; mylenie Monteskiusza z Rousseau (trójpodział — Monteskiusz, umowa społeczna i wola powszechna — Rousseau).')),

 B('Wypracowanie — XIX w.: Wiosna Ludów', M,
   T('wypracowanie', 15, 'Wiosna Ludów zakończyła się całkowitą klęską. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, narodowy i społeczny.',
     'Modelowa odpowiedź (stanowisko: teza jest nieprawdziwa — rewolucje zostały stłumione, ale przyniosły trwałe zmiany).\n\n'
     'W 1848 r. rewolucje wybuchły niemal równocześnie w Paryżu, Wiedniu, Berlinie, Mediolanie, Budapeszcie i Poznaniu. Do końca 1849 r. większość z nich stłumiono. Na pierwszy rzut oka Wiosna Ludów była więc klęską. Uważam jednak, że teza o całkowitej klęsce jest nieprawdziwa, bo wiele zdobyczy tego okresu przetrwało, a idee 1848 r. zwyciężyły w kolejnych dekadach.\n\n'
     'W aspekcie politycznym skutki były mieszane. We Francji rewolucja lutowa obaliła monarchię lipcową i wprowadziła republikę z powszechnym prawem wyborczym dla mężczyzn, ale już w 1852 r. prezydent Ludwik Napoleon ogłosił się cesarzem. W Prusach król nadał konstytucję, która, choć ograniczona, przetrwała do 1918 r. W Austrii upadł kanclerz Metternich, symbol ładu wiedeńskiego. Parlament frankfurcki nie zjednoczył Niemiec, ale pokazał, że idea zjednoczenia ma szerokie poparcie.\n\n'
     'W aspekcie narodowym ruchy niepodległościowe przegrały. Powstanie na Węgrzech stłumiła interwencja Rosji (1849), Włosi zostali pokonani przez Austrię, a Polacy przegrali w Wielkopolsce (bitwy pod Miłosławiem i Sokołowem) i w Krakowie. Jednak doświadczenia 1848 r. przygotowały zjednoczenie Włoch (1861) i Niemiec (1871), a Węgrzy w 1867 r. uzyskali autonomię w ramach Austro-Węgier.\n\n'
     'W aspekcie społecznym najtrwalszą zdobyczą było uwłaszczenie chłopów i zniesienie pańszczyzny w monarchii austriackiej. W Galicji uwłaszczenie ogłoszono już w kwietniu 1848 r., a we wrześniu parlament austriacki zniósł poddaństwo w całym państwie — tej decyzji nie cofnięto po upadku rewolucji. Rok 1848 przyniósł też ogłoszenie „Manifestu komunistycznego” i pierwsze wystąpienia robotników jako odrębnej siły politycznej (powstanie czerwcowe w Paryżu).\n\n'
     'Zwolennicy tezy podkreślają, że w krótkim okresie wszędzie zwyciężyli monarchowie, a reakcja w latach 50. była silna. To prawda w odniesieniu do lat 1849–1859, ale w dłuższej perspektywie zmiany zapoczątkowane w 1848 r. — konstytucje, uwłaszczenie, zjednoczenie narodów — zrealizowano.\n\n'
     'Ważnym skutkiem było też rozbudzenie świadomości narodowej Czechów, Słowaków, Chorwatów i Rumunów, którzy w 1848 r. po raz pierwszy wystąpili ze swoimi programami politycznymi.\n\n'
     'Podsumowując, Wiosna Ludów przegrała militarnie, ale zmieniła Europę społecznie i politycznie. Dlatego uważam, że nie była całkowitą klęską.',
     'Plan: stanowisko „nie” → polityczny (II Republika i II Cesarstwo, konstytucja pruska, upadek Metternicha, Frankfurt) → narodowy (klęski Węgrów, Włochów, Polaków / 1861, 1867, 1871) → społeczny (uwłaszczenie w Austrii, Manifest, powstanie czerwcowe) → kontrargument (reakcja lat 50.) → wniosek.\n\nTypowe błędy: opis tylko jednego kraju; pomijanie trwałych zdobyczy społecznych.')),

 B('Wypracowanie — 1914–1939: przewrót majowy', M,
   T('wypracowanie', 15, 'Przewrót majowy był dla II Rzeczypospolitej koniecznością. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, gospodarczy i ustrojowy.',
     'Modelowa odpowiedź (stanowisko: przewrót odpowiadał na realne problemy, ale nie był koniecznością — teza jest nieprawdziwa).\n\n'
     'W dniach 12–14 maja 1926 r. Józef Piłsudski, wspierany przez wierne mu oddziały, obalił rząd Wincentego Witosa i zmusił do ustąpienia prezydenta Stanisława Wojciechowskiego. W walkach w Warszawie zginęło kilkaset osób. Uważam, że przewrót był reakcją na rzeczywiste słabości państwa, ale nie był koniecznością, bo te problemy można było rozwiązywać w ramach demokracji.\n\n'
     'W aspekcie politycznym sytuacja przed 1926 r. była niestabilna. W Sejmie zasiadało kilkadziesiąt ugrupowań, rządy zmieniały się średnio co kilka miesięcy, a polityczne napięcia doprowadziły do zabójstwa pierwszego prezydenta, Gabriela Narutowicza (1922). Piłsudski krytykował „sejmokrację” i partyjniactwo. Jednak wybory do Sejmu odbywały się regularnie, a w 1923 r. i 1926 r. powstawały koalicje zdolne do rządzenia — demokracja działała, choć z trudem.\n\n'
     'W aspekcie gospodarczym kraj przeżywał trudności. Reforma Władysława Grabskiego (1924) zatrzymała hiperinflację, ale w 1925 r. złoty stracił na wartości, rosło bezrobocie, a wojna celna z Niemcami (od 1925 r.) uderzyła w eksport węgla. Zwolennicy przewrotu przekonywali, że potrzebny jest silny rząd. Warto jednak pamiętać, że poprawa koniunktury po 1926 r. wynikała w dużej mierze ze strajku górników w Wielkiej Brytanii, który otworzył rynki dla polskiego węgla, a nie z samego przewrotu.\n\n'
     'W aspekcie ustrojowym konstytucja marcowa (1921) dawała dużą władzę Sejmowi i słabą pozycję prezydentowi. Nowela sierpniowa (1926) wzmocniła władzę wykonawczą, co było rozsądną reformą. Jednak przewrót zapoczątkował rządy sanacji, które stopniowo ograniczały demokrację: proces brzeski (1931–1932), obóz w Berezie Kartuskiej (1934) i konstytucja kwietniowa (1935), która skupiła władzę w rękach prezydenta.\n\n'
     'Zwolennicy tezy podkreślają, że Piłsudski cieszył się ogromnym autorytetem, a przewrót poparła część lewicy (PPS) i robotników, licząc na naprawę państwa. To prawda — w 1926 r. wielu ludzi uważało go za konieczny. Ale cena — rozlew krwi, podział społeczeństwa i stopniowe odejście od demokracji — była wysoka.\n\n'
     'Podsumowując, przewrót majowy był odpowiedzią na prawdziwe problemy II Rzeczypospolitej, ale nie jedyną możliwą. Dlatego uważam, że nie był koniecznością.',
     'Plan: stanowisko „nie” → polityczny (rozbicie Sejmu, rządy, Narutowicz / demokracja działała) → gospodarczy (Grabski, kryzys 1925, wojna celna / strajk w Wielkiej Brytanii) → ustrojowy (konstytucja marcowa, nowela sierpniowa / Brześć, Bereza, konstytucja kwietniowa) → kontrargument (autorytet Piłsudskiego, poparcie PPS) → wniosek.\n\nTypowe błędy: pisanie, że po przewrocie Piłsudski został prezydentem (odmówił — prezydentem został Ignacy Mościcki). Oba stanowiska są dopuszczalne.')),

 B('Wypracowanie — Polska po 1945 r.: dekada Gierka', M,
   T('wypracowanie', 15, 'Lata 70. XX w. w PRL były okresem dobrobytu, który okazał się pozorny. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt gospodarczy, społeczny i polityczny.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'Edward Gierek objął władzę po krwawo stłumionych protestach na Wybrzeżu w grudniu 1970 r. Zapowiedział, że Polacy będą żyć lepiej, a hasło „Polak potrafi” miało oznaczać nowy okres w dziejach PRL. Uważam, że pierwsza połowa dekady rzeczywiście przyniosła wzrost poziomu życia, ale był to dobrobyt pozorny, bo finansowano go z zagranicznych kredytów, a nie z trwałego rozwoju gospodarki.\n\n'
     'W aspekcie gospodarczym Gierek postawił na wielkie inwestycje finansowane kredytami z Zachodu. Powstały Huta Katowice, Port Północny w Gdańsku, Trasa Łazienkowska, a na licencji włoskiego Fiata produkowano „malucha”. W pierwszych latach dochód narodowy rósł bardzo szybko. Jednak inwestycje były często nietrafione, a gospodarka centralnie planowana nie potrafiła produkować towarów konkurencyjnych na Zachodzie. W drugiej połowie dekady zadłużenie zagraniczne przekroczyło 20 mld dolarów i zaczęło przerastać możliwości spłaty.\n\n'
     'W aspekcie społecznym poprawa była odczuwalna. Rosły płace, w sklepach pojawiło się więcej towarów, w tym zachodnie produkty (Coca-Cola), budowano masowo bloki mieszkalne, a wielu ludzi mogło po raz pierwszy kupić samochód czy telewizor. Jednak już w 1976 r., gdy rząd ogłosił drastyczne podwyżki cen żywności, wybuchły protesty w Radomiu, Ursusie i Płocku. Pod koniec dekady wróciły braki towarów, a w 1976 r. wprowadzono kartki na cukier.\n\n'
     'W aspekcie politycznym władza zabiegała o poparcie przez konsumpcję, ale nie zmieniła istoty systemu. W 1976 r. do konstytucji wpisano kierowniczą rolę PZPR i sojusz ze ZSRS, co wywołało protesty intelektualistów. Po represjach wobec robotników powstał Komitet Obrony Robotników (KOR), a potem inne organizacje opozycyjne. Wybór Polaka na papieża (1978) i pielgrzymka Jana Pawła II (1979) pokazały siłę niezależnego społeczeństwa.\n\n'
     'Zwolennicy przeciwnego poglądu przypominają, że wiele inwestycji tamtego okresu, jak drogi, mosty czy osiedla, służyło ludziom przez kolejne dekady. To prawda, ale za kredyty Gierka płaciły następne pokolenia, a zadłużenie stało się jedną z przyczyn kryzysu lat 80.\n\n'
     'Podsumowując, dekada Gierka przyniosła krótkotrwałą poprawę życia, ale jej koszty doprowadziły do kryzysu i strajków w sierpniu 1980 r. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → gospodarczy (kredyty, inwestycje, „maluch”, zadłużenie) → społeczny (płace, mieszkania / 1976 Radom, Ursus, kartki) → polityczny (konstytucja 1976, KOR, papież) → kontrargument (trwałe inwestycje) → wniosek z rokiem 1980.\n\nTypowe błędy: mylenie wydarzeń 1970 (Wybrzeże, koniec rządów Gomułki) i 1976 (Radom, Ursus); brak liczb dotyczących zadłużenia.')),

 B('Wypracowanie — świat po 1945 r.: zimna wojna', M,
   T('wypracowanie', 15, 'Zimna wojna była przede wszystkim konfliktem ideologicznym. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt ideologiczny, militarny i gospodarczy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, bo spór ideologiczny nadawał sens rywalizacji militarnej i gospodarczej).\n\n'
     'Zimna wojna trwała od drugiej połowy lat 40. do rozpadu ZSRS w 1991 r. Nie doszło w niej do bezpośredniej wojny między supermocarstwami, ale ich rywalizacja obejmowała cały świat. Uważam, że był to przede wszystkim konflikt ideologiczny — starcie dwóch wizji świata, które nadawało sens wyścigowi zbrojeń i rywalizacji gospodarczej.\n\n'
     'W aspekcie ideologicznym naprzeciw siebie stanęły dwa systemy. Stany Zjednoczone broniły demokracji liberalnej, wolnego rynku i praw jednostki, a ZSRS — komunizmu, gospodarki planowej i dyktatury partii. Doktryna Trumana (1947) zapowiadała pomoc dla „wolnych narodów” zagrożonych komunizmem, a doktryna Breżniewa (1968) uzasadniała interwencje w obronie „zdobyczy socjalizmu”. Obie strony prowadziły propagandę: Radio Wolna Europa nadawało dla krajów bloku wschodniego, a ZSRS wspierał partie komunistyczne na Zachodzie.\n\n'
     'W aspekcie militarnym powstały dwa bloki: NATO (1949) i Układ Warszawski (1955). Wyścig zbrojeń, zwłaszcza jądrowych, prowadził do kryzysów, w których świat stawał na krawędzi wojny, jak kryzys kubański (1962). Supermocarstwa walczyły jednak pośrednio — w Korei (1950–1953), Wietnamie czy Afganistanie — wspierając strony konfliktów, które same miały charakter ideologiczny: komuniści przeciw antykomunistom.\n\n'
     'W aspekcie gospodarczym rywalizacja także odzwierciedlała spór ideologiczny. Plan Marshalla (1947) odbudował gospodarkę Europy Zachodniej, a ZSRS odpowiedział utworzeniem RWPG (1949) i zakazał krajom bloku przyjęcia pomocy. Wyścig kosmiczny — od Sputnika (1957) po lądowanie Amerykanów na Księżycu (1969) — miał dowieść wyższości jednego systemu nad drugim.\n\n'
     'Zwolennicy przeciwnego poglądu przekonują, że zimna wojna była przede wszystkim rywalizacją dwóch mocarstw o strefy wpływów, a ideologia służyła jako uzasadnienie. Na to wskazują np. sojusz USA z niedemokratycznymi reżimami czy konflikt ZSRS z komunistycznymi Chinami. To ważny argument, ale bez ideologii trudno wyjaśnić, dlaczego konflikt objął cały świat i zakończył się wraz z upadkiem komunizmu.\n\n'
     'Ideologiczny charakter konfliktu widać też w Europie Środkowej: w 1956 r. na Węgrzech i w 1968 r. w Czechosłowacji ZSRS interweniował zbrojnie, by nie dopuścić do odejścia od komunizmu.\n\n'
     'Podsumowując, zimna wojna miała wymiar militarny i gospodarczy, ale jej istotą był spór dwóch systemów ideologicznych. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → ideologiczny (demokracja vs komunizm, doktryny Trumana i Breżniewa, propaganda) → militarny (NATO, Układ Warszawski, Kuba 1962, wojny zastępcze) → gospodarczy (plan Marshalla, RWPG, wyścig kosmiczny) → kontrargument (geopolityka, sojusze z dyktaturami, spór z Chinami) → wniosek.\n\nTypowe błędy: wymienianie samych kryzysów bez odniesienia do tezy; podawanie złej daty końca zimnej wojny.')),
]
